using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
public static class PatchHttpEngine{
 static IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
 static string Name(string s){return s.Replace("Stream To Earn","ShenPulse").Replace("StreamToEarn","ShenPulse").Replace("S2E","ShenPulse").Replace("s2e","shenpulse").Replace("streamtoearn.io","shenpulse.leuridan.fr");}
 public static void Main(string[] a){var keys=File.ReadAllLines(a[2]);var values=File.ReadAllLines(a[3]);var lookup=new Dictionary<string,string>();for(int n=0;n<keys.Length;n++)lookup[keys[n]]=Name(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(values[n])));int replaced=0,remaining=0,port=0;
 using(var m=ModuleDefinition.ReadModule(a[0])){foreach(var t in Types(m.Types)){foreach(var attr in t.CustomAttributes)for(int k=0;k<attr.ConstructorArguments.Count;k++){var old=attr.ConstructorArguments[k];if(old.Value is string)attr.ConstructorArguments[k]=new CustomAttributeArgument(old.Type,Name((string)old.Value));}
 foreach(var method in t.Methods.Where(x=>x.HasBody))foreach(var i in method.Body.Instructions){if(i.OpCode==OpCodes.Ldstr)i.Operand=Name((string)i.Operand);if(i.OpCode==OpCodes.Ldc_I4&&(int)i.Operand==55001){i.Operand=int.Parse(a[4]);port++;}var g=i.Operand as GenericInstanceMethod;if(g==null||g.DeclaringType.Name!="<Module>"||g.GenericArguments[0].FullName!="System.String")continue;var p=i.Previous;while(p!=null&&(p.OpCode==OpCodes.Nop||((p.OpCode==OpCodes.Br_S||p.OpCode==OpCodes.Br)&&p.Operand==i)))p=p.Previous;int id;if(p!=null&&p.OpCode==OpCodes.Ldc_I4)id=(int)p.Operand;else if(p!=null&&p.OpCode==OpCodes.Ldc_I4_S)id=(sbyte)p.Operand;else{remaining++;continue;}string value;if(!lookup.TryGetValue(g.ElementMethod.MetadataToken.ToUInt32()+":"+id,out value)){remaining++;continue;}p.OpCode=OpCodes.Nop;p.Operand=null;i.OpCode=OpCodes.Ldstr;i.Operand=value;replaced++;}}
 if(remaining!=0||port!=1)throw new Exception("Unexpected constant layout "+remaining+" "+port);foreach(var attr in m.Assembly.CustomAttributes)for(int k=0;k<attr.ConstructorArguments.Count;k++){var old=attr.ConstructorArguments[k];if(old.Value is string)attr.ConstructorArguments[k]=new CustomAttributeArgument(old.Type,Name((string)old.Value));}m.Assembly.Name.Name=a[5];m.Name=a[5]+".dll";m.Write(a[1]);Console.WriteLine(replaced+" string sites replaced; one private port");}}
}